-- =============================================================================
-- The List Builder SIC tree, from Sean's complete sheet (SIC_ListBuildingSheet-COMPLETE_2026-10-27):
-- exactly the sectors, groups and codes on it, in its order, with each code's Industry Class
-- (a grouping across the tree: Artisan-Special Trade Contractors holds 0781 Landscape Counseling as
-- well as the 17xx trades). Codes not on the sheet leave the tree (the 60s but 64 and 65, 88, 96-99).
-- An administrator can load a newer sheet the same way from the List Builder page.
-- =============================================================================

alter table public.list_sic add column if not exists class text;

drop table if exists pg_temp.sheet;
create temporary table sheet (code text, name text, kind text, parent text, sort int, class text);

-- Parents first, so each one is there for what sits under it.
select s.code, s.name, s.kind, null, s.sort, s.class from sheet s
on conflict (code) do update set name = excluded.name, kind = excluded.kind, sort = excluded.sort, class = excluded.class;
update public.list_sic l set parent = s.parent from sheet s where s.code = l.code and l.parent is distinct from s.parent;
delete from public.list_sic l where not exists (select 1 from sheet s where s.code = l.code);
drop table if exists pg_temp.sheet;
